#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
#
# Nuances 自動發文設定：Supabase（放公開媒體）→ Instagram → Threads → Facebook 粉專 → TikTok → YouTube → 上傳雲端。
# 在專案根目錄跑：bash skills/promo-queue/scripts/setup_wizard.sh
# 一次設定一個國家（channel，例如 tw、jp）的帳號；要加國家就重跑一次選新的代號。
# 每個平台都可以先跳過，之後重跑只設那一個。值記在 ~/.config/nuances-promo/wizard.<國家>.env，
# 完成的平台寫進本機 secrets.json，最後只把「這次有完成的平台」傳到雲端（postq.py 會在雲端輪替 token，跳過的平台不覆蓋）。

TOTAL_STAGES=11

CONF_DIR="$HOME/.config/nuances-promo"
mkdir -p "$CONF_DIR"; chmod 700 "$CONF_DIR"
ENV_FILE="$CONF_DIR/wizard.env"   # 第 1 步選好國家後換成 wizard.<國家>.env，各國帳號分開記
SECRETS_JSON="$CONF_DIR/secrets.json"
SCRIPTS="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO="$(cd "$SCRIPTS/../../.." && pwd)"
BUCKET="promo-media"
DONE=()   # 這次有完成的平台

# py：跑一段 Python（有 requests），參數用環境變數傳，避免金鑰出現在指令列
py() { python3 -c "$1"; }

# save_section NAME JSON：把一段設定合併進 secrets.json
save_section() {
  SECTION="$1" BODY="$2" OUT="$SECRETS_JSON" py '
import json, os, pathlib
p = pathlib.Path(os.environ["OUT"])
d = json.loads(p.read_text()) if p.exists() else {}
d[os.environ["SECTION"]] = {**d.get(os.environ["SECTION"], {}), **json.loads(os.environ["BODY"])}
p.write_text(json.dumps(d, indent=1)); p.chmod(0o600)'
  DONE+=("$1")
  printf '  %s✓ saved%s %s → %s\n' "$GREEN" "$RESET" "$1" "$SECRETS_JSON"
}

# ask_code VAR "提示"：貼上授權後跳轉的整段網址，取出 code
ask_code() {
  local url
  printf '  %s%s%s ' "$BOLD" "$2" "$RESET"
  read -r url || true
  printf -v "$1" '%s' "$(URL="$url" py '
import os, urllib.parse as u
q = u.parse_qs(u.urlparse(os.environ["URL"].strip()).query)
print(q.get("code", [""])[0].removesuffix("#_"))')"
}

banner "Nuances 自動發文設定"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "開始前確認"
say "這個精靈會幫你把 4 個平台的發文和成效權限接好，最後開啟雲端自動發文。"
say "先確認這些帳號都已經存在（沒有的話先去 App 裡建好）："
step "Instagram：Nuances 的帳號要切成「專業帳號」（商業或創作者都可以）"
step "Threads：用同一個 Instagram 帳號登入過 Threads"
step "Facebook：Nuances 的粉絲專頁（你要是粉專管理員）"
step "TikTok：Nuances 的 TikTok 帳號"
step "YouTube：Nuances 的 Google 帳號，底下已經有頻道"
step "GitHub CLI 已登入（gh auth status），精靈要幫 repo 設定兩個 secret"
note "任何一個平台還沒準備好，到那一步選 N 跳過就好，之後重跑精靈再補。"
say ""
say "每個國家是一組獨立的帳號。這次要設定哪個國家？"
note "代號用兩個小寫字母：tw 台灣、hk 香港、jp 日本、kr 韓國、my 馬來西亞…（現有的國家：$(cd "$REPO" && python3 "$SCRIPTS/postq.py" channel list 2>/dev/null | awk '{print $1}' | paste -sd ' ' - || true)）"
printf '  %s國家代號（Enter = tw）：%s ' "$BOLD" "$RESET"
read -r CHANNEL || true
CHANNEL="${CHANNEL:-tw}"
ENV_FILE="$CONF_DIR/wizard.$CHANNEL.env"
touch "$ENV_FILE"; chmod 600 "$ENV_FILE"
if [[ "$CHANNEL" != tw ]]; then
  warn "TikTok 帳號的地區在註冊時就決定了：$CHANNEL 的 TikTok 帳號要用當地門號或當地網路註冊，才會被推給當地的人。"
fi
pause "都確認好了就按 Enter"

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Supabase：放公開媒體的空間"
say "IG 和 Threads 只能從公開網址抓影片 / 圖片，所以發文前會先傳到 Supabase Storage。"
SUPABASE_URL=$(grep -E '^EXPO_PUBLIC_SUPABASE_URL=' "$REPO/.env" 2>/dev/null | tail -n1 | cut -d= -f2- | tr -d '"' || true)
[[ -z "$SUPABASE_URL" ]] && ask SUPABASE_URL "Supabase 專案網址（https://xxx.supabase.co）："
note "專案：$SUPABASE_URL"
open_url "https://supabase.com/dashboard/project/$(printf '%s' "$SUPABASE_URL" | sed -E 's#https://([^.]+)\..*#\1#')/settings/api-keys"
step "在 API Keys 頁面找到 service_role（或 Secret keys 底下的 secret key），按 Reveal 後複製"
warn "這把鑰匙權限很大，只會存在你這台 Mac 的 $CONF_DIR，不會進 git"
# 設過別的國家時，Supabase 金鑰已經在 secrets.json，直接帶入（Enter 沿用）
if [[ -z "$(_existing SUPABASE_SERVICE_KEY || true)" ]]; then
  PREV=$(python3 -c 'import json,os;print(json.load(open(os.path.expanduser("~/.config/nuances-promo/secrets.json"))).get("supabase",{}).get("service_key",""))' 2>/dev/null || true)
  [[ -n "$PREV" ]] && printf 'SUPABASE_SERVICE_KEY=%s\n' "$PREV" >> "$ENV_FILE"
fi
ask_secret SUPABASE_SERVICE_KEY "貼上 service key："
write_env SUPABASE_SERVICE_KEY "$SUPABASE_SERVICE_KEY"
say "建立公開 bucket「$BUCKET」，並放一個授權用的回呼頁…"
KEY="$SUPABASE_SERVICE_KEY" URL="$SUPABASE_URL" B="$BUCKET" py '
import os, requests
h = {"Authorization": "Bearer " + os.environ["KEY"], "apikey": os.environ["KEY"]}
u, b = os.environ["URL"].rstrip("/"), os.environ["B"]
r = requests.post(f"{u}/storage/v1/bucket", headers=h, json={"id": b, "name": b, "public": True}, timeout=30)
if r.status_code >= 400 and "already exists" not in r.text.lower() and r.status_code != 409:
    raise SystemExit(f"建立 bucket 失敗：{r.status_code} {r.text}")
r = requests.post(f"{u}/storage/v1/object/{b}/oauth/callback.txt", timeout=30,
                  headers={**h, "Content-Type": "text/plain; charset=utf-8", "x-upsert": "true"},
                  data="授權完成。把瀏覽器網址列的整段網址複製回設定精靈。".encode())
if r.status_code >= 400:
    raise SystemExit(f"上傳測試檔失敗：{r.status_code} {r.text}")
print("  ok")'
CALLBACK="${SUPABASE_URL%/}/storage/v1/object/public/$BUCKET/oauth/callback.txt"
write_env CALLBACK "$CALLBACK"
save_section supabase "{\"url\": \"$SUPABASE_URL\", \"service_key\": \"$SUPABASE_SERVICE_KEY\", \"bucket\": \"$BUCKET\"}"
say "Threads / TikTok 授權時用的回呼網址（等一下會用到）："
say "${BOLD}$CALLBACK${RESET}"
pause

# ── 3 ────────────────────────────────────────────────────────────────────
stage "Meta：建立 App（IG + Threads + Facebook 共用）"
if confirm "要設定 Instagram / Threads / Facebook 嗎？"; then
  DO_META=1
  open_url "https://developers.facebook.com/apps/creation/"
  note "已經為別的國家建過 Meta App 的話，不用再建：直接按 Enter 到下一步，用同一個 App 加這個國家的帳號。"
  step "用管理 Nuances IG 的 Facebook 帳號登入（第一次會要你註冊成開發者，照畫面走）"
