  note "    「管理 Instagram 上的訊息和內容」(Manage messaging & content on Instagram)"
  note "    「存取 Threads API」(Access the Threads API)"
  note "    「管理粉絲專頁上的所有內容」(Manage everything on your Page)"
  note "    如果不能同時勾兩個，就先勾 Instagram，之後在 App 的「使用案例」再加 Threads；還是不行就各建一個 App"
  step "商家帳號可以先不連，一路按下一步到建立完成"
  note "不用送審：App 維持開發模式，就能發文到你自己（有角色）的帳號。"
  pause "App 建好了就按 Enter"
else
  DO_META=0
  SKIPPED+=("Instagram / Threads / Facebook（之後重跑精靈）")
fi

# ── 4 ────────────────────────────────────────────────────────────────────
stage "Instagram：產生發文 token"
if [[ "$DO_META" == 1 ]]; then
  step "在 App 後台左邊選「使用案例」→ Instagram 那一項按「自訂」"
  step "選「使用 Instagram 登入的 API 設定」(API setup with Instagram login)"
  step "權限要有 instagram_business_basic、instagram_business_content_publish、instagram_business_manage_insights（沒有就按新增）"
  step "第 2 段「產生存取權杖」→「新增帳號」→ 登入 $CHANNEL 這個國家的 Nuances IG 帳號"
  note "    如果要你接受測試者邀請：IG App → 設定 → 應用程式和網站 → 測試者邀請 → 接受"
  step "帳號出現後按「產生權杖」，勾同意後複製那串 token"
  ask_secret IG_TOKEN "貼上 Instagram token："
  IG_JSON=$(TOK="$IG_TOKEN" py '
import os, json, time, requests
r = requests.get("https://graph.instagram.com/v21.0/me", params={"fields": "user_id,username", "access_token": os.environ["TOK"]}, timeout=30)
if r.status_code >= 400: raise SystemExit(f"token 驗證失敗：{r.text}")
j = r.json()
print(json.dumps({"user_id": str(j.get("user_id") or j["id"]), "username": j.get("username", ""),
                  "token": os.environ["TOK"], "token_expires": int(time.time()) + 59 * 86400}))') || { warn "Instagram token 無效，這次先跳過"; IG_JSON=""; }
  if [[ -n "$IG_JSON" ]]; then
    write_env IG_TOKEN "$IG_TOKEN"
    save_section instagram "$IG_JSON"
    note "帳號：@$(printf '%s' "$IG_JSON" | python3 -c 'import json,sys;print(json.load(sys.stdin)["username"])')"
  else
    SKIPPED+=("Instagram token")
  fi
  pause
else
  note "跳過"; pause
fi

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Threads：授權"
if [[ "$DO_META" == 1 ]] && confirm "要設定 Threads 嗎？"; then
  step "App 後台 →「使用案例」→ Threads 那一項按「自訂」"
  step "權限加上 threads_basic、threads_content_publish、threads_manage_insights"
  step "「設定」裡的「回呼網址」(Redirect Callback URLs) 貼上：$CALLBACK"
  note "    另外兩個「解除安裝 / 刪除」回呼網址也填同一個就好"
  step "同一頁複製「Threads 應用程式編號」和「Threads 應用程式密鑰」"
  step "「應用程式角色」→「角色」→ 新增 Threads 測試者 → 輸入 Nuances 的 Threads 帳號"
  note "    再到 Threads App → 設定 → 帳號 → 網站權限 → 邀請 → 接受"
  ask TH_APP_ID "Threads 應用程式編號："
  ask_secret TH_APP_SECRET "Threads 應用程式密鑰："
  write_env TH_APP_ID "$TH_APP_ID"; write_env TH_APP_SECRET "$TH_APP_SECRET"
  open_url "https://threads.net/oauth/authorize?client_id=$TH_APP_ID&redirect_uri=$(CB="$CALLBACK" py 'import os,urllib.parse as u;print(u.quote(os.environ["CB"],safe=""))')&scope=threads_basic,threads_content_publish,threads_manage_insights&response_type=code"
  step "在打開的頁面按允許。跳轉後會看到一行中文說明，把網址列整段複製回來"
  ask_code TH_CODE "貼上跳轉後的整段網址："
  TH_JSON=$(ID="$TH_APP_ID" SEC="$TH_APP_SECRET" CODE="$TH_CODE" CB="$CALLBACK" py '
import os, json, time, requests
e = os.environ
r = requests.post("https://graph.threads.net/oauth/access_token", timeout=30, data={"client_id": e["ID"], "client_secret": e["SEC"],
    "grant_type": "authorization_code", "redirect_uri": e["CB"], "code": e["CODE"]})
if r.status_code >= 400: raise SystemExit(f"換 token 失敗：{r.text}")
short = r.json()["access_token"]
r = requests.get("https://graph.threads.net/access_token", timeout=30,
                 params={"grant_type": "th_exchange_token", "client_secret": e["SEC"], "access_token": short})
if r.status_code >= 400: raise SystemExit(f"換長效 token 失敗：{r.text}")
j = r.json()
me = requests.get("https://graph.threads.net/v1.0/me", params={"fields": "id,username", "access_token": j["access_token"]}, timeout=30).json()
print(json.dumps({"user_id": me["id"], "username": me.get("username", ""), "token": j["access_token"],
                  "token_expires": int(time.time()) + int(j.get("expires_in", 5184000))}))') || { warn "Threads 授權失敗，這次先跳過"; TH_JSON=""; }
  if [[ -n "$TH_JSON" ]]; then save_section threads "$TH_JSON"; else SKIPPED+=("Threads 授權"); fi
  pause
else
  note "跳過"; pause
fi

# ── 5b ───────────────────────────────────────────────────────────────────
stage "Facebook 粉專：授權"
if [[ "$DO_META" == 1 ]] && confirm "要設定 Facebook 粉專嗎？"; then
  step "App 後台 →「使用案例」→「管理粉絲專頁上的所有內容」按「自訂」，權限加上："
